{
  "narrative_summary": "This result rests on the link from Audit Completion to Annual Recurring Revenue. In this model, Launch in March breaches the audit constraint stated in the brief and is not available. Launch in June is the feasible alternative.",
  "story_headlines": {
    "opt_march": "Launch in March breaches the audit constraint and cannot proceed as modelled.",
    "opt_june": "Launch in June remains feasible once the audit has closed, as the brief requires."
  },
  "robustness_explanation": {
    "summary": "The ordering holds in about 68% of variations, though the audit constraint overrides it for Launch in March.",
    "primary_risk": "The link from Audit Completion to Annual Recurring Revenue, since shipping cannot happen before the audit closes.",
    "stability_factors": [
      "Early Demand consistently supports Annual Recurring Revenue across variations"
    ],
    "fragility_factors": [
      "The link from Audit Completion to Annual Recurring Revenue could flip which option more runs support"
    ]
  },
  "readiness_rationale": "The brief states shipping cannot happen before the audit closes, and Launch in March as modelled breaches that condition, so the framing needs to rule it out before a date is settled.",
  "evidence_enhancements": {},
  "scenario_contexts": {
    "edge_audit_arr": {
      "trigger_description": "If Audit Completion slips later than assumed in the link to Annual Recurring Revenue...",
      "consequence": "...then the most runs would support Launch in June rather than Launch in March."
    }
  },
  "flip_thresholds": [],
  "bias_findings": [],
  "key_assumptions": [
    "The link from Audit Completion to Annual Recurring Revenue assumes the audit timeline stated in the brief is accurate",
    "The link from Early Demand to Annual Recurring Revenue assumes current market conditions hold"
  ],
  "decision_quality_prompts": [
    {
      "question": "What would have to be true about the audit timeline for Launch in March to become feasible?",
      "principle": "Consider-the-opposite",
      "applies_because": "The modelled option most runs supported is barred by a stated constraint, so testing what would remove that constraint clarifies the real choice."
    },
    {
      "question": "How would delaying to Launch in June feel once the audit has closed and the constraint no longer applies?",
      "principle": "10-10-10 (Welch)",
      "applies_because": "The options are close enough that the practical feel of each timing matters as much as the modelled share."
    }
  ],
  "framing_check": {
    "addresses_goal": false,
    "concern": "The brief rules out shipping before the audit closes, but the option the most runs supported in this model does exactly that, so the option set as modelled does not respect the stated constraint.",
    "suggested_reframe": "Frame the options around dates that are only reachable after the audit closes, then compare those against Annual Recurring Revenue."
  }
